2841		tools := make([]ReviewToolDisposition, 0, len(bundle.Payload.Plan.Tools))
2842		for _, tool := range bundle.Payload.Plan.Tools {
2843			disposition := ReviewToolDisposition{
2844				ID:        tool.ID,
2845				Component: tool.Component,
2846			}
2847			if containsFold(tool.Preconditions, "review-complete") {
2848				disposition.Disposition = "deferred"
2849				disposition.Rationale = "post-review gate"
2850			} else if tool.ProducerCoverage == "none" {
2851				// A fact the engine computed from the matrix, not a judgment: this
2852				// component declares that it runs no check, so nothing can produce
2853				// what the tool asks for. Preparing it here is what keeps the
2854				// reviewer from having to cite another component's result.
2855				disposition.Disposition = "not-used"
2856				disposition.Rationale = "the validation matrix declares this component runs no check, so no producer can emit evidence of class " + strings.Join(tool.EvidenceClasses, "|")
2857			} else if tool.Requiredness == "recommended" {
2858				disposition.Disposition = "not-used"
2859				disposition.Rationale = "not used during automated attestation"
2860			} else {
2861				toolEv := ""
2862				toolComponents := []string{}
2863				if tool.Component != "" {
2864					toolComponents = append(toolComponents, tool.Component)
2865				}
2866				toolEv = pickScoped(tool.EvidenceClasses, toolComponents)
2867				if toolEv == "" && len(tool.EvidenceClasses) == 0 {
2868					// A tool that declares no evidence class does not report a
2869					// validation result at all — `artifact-check` and `review-check`
2870					// are POSE commands, and what supports their disposition is that
2871					// the command ran. Naming the tool is a real reference to that;
2872					// reaching for an unrelated sealed result, as this used to, said
2873					// nothing about whether the tool ran.
2874					toolEv = "check:" + tool.ID
2875				}
2876				if toolEv == "" {
2877					// The same invention the criteria path stopped doing one spec
2878					// ago, on the other half of the attestation: `validation:auto-
2879					// attest`, `<class>:auto-attest`, `docs:auto-attest` — none of
2880					// them pointing at anything, and nothing downstream checking.
2881					// The distinction between a judged review and a stamped one
2882					// does not survive one half of it being fabricated.
2883					if requiresEvidence {
2884						if len(tool.EvidenceClasses) > 0 {
2885							return ReviewAttestation{}, nil, fmt.Errorf("pose: review tool %s requires evidence class %s and bundle %s seals none; run the tool, or record its disposition with `pose review attest --tool`", tool.ID, strings.Join(tool.EvidenceClasses, "|"), bundleID)
2886						}
2887						return ReviewAttestation{}, nil, fmt.Errorf("pose: review tool %s has no evidence in bundle %s; run the tool, or record its disposition with `pose review attest --tool`", tool.ID, bundleID)
2888					}
2889					// `deferred`, not `not-used`: a required tool recorded not-used
2890					// is a blocker whatever the reason, while a deferral is the
2891					// disposition the engine already accepts for a tool whose
2892					// precondition this scope cannot meet.
2893					disposition.Disposition = "deferred"
2894					disposition.Rationale = "the scope carries no delivery target, so no evidence this tool reports is collected for it"
2895					tools = append(tools, disposition)
2896					continue
2897				}
2898				disposition.Disposition = "passed"
2899				disposition.Evidence = toolEv
2900			}
